import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('trabajar-por-la-comida-que-permanece', 'B',
 [dict(t=6, e=52, titulo='Paz en medio de la tormenta', txt='Empieza una cosa injusta, empieza una aflicción, y el Señor lo que ha venido es darte paz en medio de la tormenta. Esa paz que es sobre todo entendimiento, hermano, es una paz no ficticia, es una paz verdadera: usted puede cometer errores, pero Dios está ahí con usted. Usted siente la presencia del Señor; siente cómo lo agarra de la mano, lo levanta, lo sacude […]. Hermano, realmente tener paz no tiene precio, no se lo puede dar el dinero. Usted no puede ir a decir: «Bueno, voy a comprar cincuenta quintales de paz». No se puede.'),
  dict(t=212, e=265, titulo='La comida de Jesús es hacer la voluntad del Padre', txt='Juan 4:34 dice: «Jesús les dijo: Mi comida es que haga la voluntad del que me envió». Fíjese qué tremenda. ¿Cuántos quieren saber la comida de Jesús? Entonces, ¿cómo quieres saber cuál es la comida que Dios da? Tienes que entregar tu voluntad hoy. Aquí hay un gran rollo, porque cada persona quiere vivir como le da la gana y quiere buscar a Dios como le da la gana. Pero así no nos vamos a poder ir; nosotros necesitamos agradar a Dios.'),
  dict(t=497, e=545, titulo='Trabajad por la comida que permanece', txt='Y respondió Jesús y le dijo: «De cierto, de cierto os digo que me buscáis […] para saciaros. Trabajad —aquí viene la clave— no por la comida que perece, sino por la comida que a vida eterna permanece». Entonces usted tiene que preocuparse por lo eterno. ¿Por qué? Porque usted es eterno. Usted y yo estamos practicando la vida eterna. Por eso usted ya no va a poder ser malo, porque no va a ser malo eternamente: va a ser un hijo de Dios santificado, limpiado por la sangre de Jesucristo.')],
 [dict(t=93, txt='Lo que Dios quiere es que usted tenga justicia en su vida, que tenga paz en su corazón y que tenga gozo en todo su ser.'),
  dict(t=318, txt='Si usted no hace la voluntad del Padre, no comió, y esa persona se va a desnutrir y no va a poder hacer lo que tiene que hacer.'),
  dict(t=585, txt='¿Qué le va a dar el Hijo del Hombre? Vida eterna. Usted ya está practicando la vida eterna.')],
 ['¿Qué parte de tu voluntad necesitas entregarle hoy al Señor para dejar de vivir «como te da la gana»?',
  '¿Qué paz o qué gozo has perdido, y qué estás esperando en el Señor para que regrese?',
  '¿En qué estás trabajando más: en la comida que perece o en la que permanece para vida eterna?'])
